(function(){
  function extractPost(html, filename){
    var titleMatch = html.match(/<title>([^<]*)<\/title>/i);
    var title = titleMatch ? titleMatch[1].replace(/\s*[—–-]\s*Amarbir Singh\s*$/i,'').trim() : filename;
    var dateMatch = html.match(/<meta\s+name=["']date["']\s+content=["']([^"']*)["']/i);
    var date = dateMatch ? dateMatch[1] : (filename.match(/^(\d{4}-\d{2}-\d{2})/) ? filename.match(/^(\d{4}-\d{2}-\d{2})/)[1] : '');
    var excerptMatch = html.match(/<meta\s+name=["']excerpt["']\s+content=["']([^"']*)["']/i);
    var excerpt = excerptMatch ? excerptMatch[1] : '';
    return { title: title, date: date, excerpt: excerpt, url: '/blogs/' + filename };
  }

  function parseDirectoryListing(listHtml){
    var files = [];
    var re = /<a\s+href=["']([^"']+\.html)["']/gi;
    var m;
    while((m = re.exec(listHtml)) !== null){
      var f = decodeURIComponent(m[1]);
      if(f === 'index.html' || f === 'template.html') continue;
      if(/^\d{4}-\d{2}-\d{2}-.*\.html$/i.test(f)) files.push(f);
    }
    return files;
  }

  function loadPosts(){
    return fetch('/blogs/index.json')
      .then(function(r){ if(!r.ok) throw new Error('no index'); return r.json(); })
      .then(function(data){ return (data.posts || []); })
      .catch(function(){
        return fetch('/blogs/')
          .then(function(r){ if(!r.ok) throw new Error('no listing'); return r.text(); })
          .then(function(html){
            var files = parseDirectoryListing(html);
            return Promise.all(files.map(function(f){
              return fetch('/blogs/' + f).then(function(r){ return r.text(); }).then(function(text){
                return extractPost(text, f);
              });
            }));
          });
      });
  }

  loadPosts().then(function(posts){
    if(!posts.length) return;
    posts.sort(function(a,b){ return b.date.localeCompare(a.date) || b.title.localeCompare(a.title); });
    var recent = posts.slice(0, 3);
    var list = document.getElementById('writing-list');
    var section = document.getElementById('writing');
    if(!list || !section) return;
    list.innerHTML = recent.map(function(p){
