// Minimal GitHub Issues engagement widget for blog posts
// Requires <meta name="github-issue" content="ISSUE_NUMBER"> in the post <head>
(function(){
  var meta = document.querySelector('meta[name="github-issue"]');
  var issue = meta && meta.getAttribute('content');
  if(!issue) return;

  var repo = 'a-5ingh/singhamarbir.com';
  var apiUrl = 'https://api.github.com/repos/' + repo + '/issues/' + issue;
  var issueUrl = 'https://github.com/' + repo + '/issues/' + issue;

  var likeBtn = document.getElementById('like-btn');
  var likeCount = document.getElementById('like-count');
  var commentsLink = document.getElementById('comments-link');

  if(likeBtn) likeBtn.href = issueUrl;
  if(commentsLink) commentsLink.href = issueUrl;

  fetch(apiUrl, { headers: { 'Accept': 'application/vnd.github+json' } })
    .then(function(r){ return r.ok ? r.json() : null; })
    .then(function(data){
      if(!data) return;
      var reactions = data.reactions && data.reactions.total_count || 0;
      var comments = data.comments || 0;
      if(likeCount) likeCount.textContent = reactions;
      if(commentsLink) commentsLink.textContent = comments + (comments === 1 ? ' comment' : ' comments');
    })
    .catch(function(){});
})();

