// Post a heart reaction to a GitHub issue
export async function onRequestPost(context) {
  const { request, env } = context;
  const cookieHeader = request.headers.get('Cookie') || '';
  const tokenMatch = cookieHeader.match(/gh_token=([^;]+)/);

  if (!tokenMatch) {
    return jsonError('Unauthorized', 401);
  }

  const token = tokenMatch[1];
  let body;
  try {
    body = await request.json();
  } catch (e) {
    return jsonError('Invalid JSON body', 400);
  }

  const issue = body.issue;
  if (!issue) {
    return jsonError('Missing issue number', 400);
  }

  const res = await fetch(`https://api.github.com/repos/a-5ingh/personal/issues/${issue}/reactions`, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${token}`,
      'Accept': 'application/vnd.github+json',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ content: 'heart' })
  });

  if (!res.ok) {
    const errText = await res.text();
    console.error('GitHub like API error:', res.status, errText);
    return jsonError(`GitHub API error: ${res.status} ${errText}`, res.status);
  }

  const data = await res.json();
  return new Response(JSON.stringify(data), { headers: { 'Content-Type': 'application/json' } });
}

function jsonError(message, status) {
  return new Response(JSON.stringify({ error: message }), {
    status,
    headers: { 'Content-Type': 'application/json' }
  });
}

// Post a comment to a GitHub issue
export async function onRequestPost(context) {
  const { request, env } = context;
  const cookieHeader = request.headers.get('Cookie') || '';
  const tokenMatch = cookieHeader.match(/gh_token=([^;]+)/);

  if (!tokenMatch) {
    return jsonError('Unauthorized', 401);
  }

  const token = tokenMatch[1];
  let body;
  try {
    body = await request.json();
  } catch (e) {
    return jsonError('Invalid JSON body', 400);
  }

  const issue = body.issue;
  const text = body.text;
  if (!issue || !text || !text.trim()) {
    return jsonError('Missing issue or comment text', 400);
  }

  const res = await fetch(`https://api.github.com/repos/a-5ingh/personal/issues/${issue}/comments`, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${token}`,
      'Accept': 'application/vnd.github+json',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ body: text.trim() })
  });

  if (!res.ok) {
    const errText = await res.text();
    console.error('GitHub comment API error:', res.status, errText);
    return jsonError(`GitHub API error: ${res.status} ${errText}`, res.status);
  }

  const data = await res.json();
  return new Response(JSON.stringify(data), { headers: { 'Content-Type': 'application/json' } });
}

function jsonError(message, status) {
  return new Response(JSON.stringify({ error: message }), {
    status,
    headers: { 'Content-Type': 'application/json' }
  });
}

// Debug endpoint: checks GitHub token validity and scope hints
export async function onRequestGet(context) {
  const { request } = context;
  const cookieHeader = request.headers.get('Cookie') || '';
  const tokenMatch = cookieHeader.match(/gh_token=([^;]+)/);

  if (!tokenMatch) {
    return new Response(JSON.stringify({ authed: false, message: 'No gh_token cookie' }), {
      headers: { 'Content-Type': 'application/json' }
    });
  }

  const token = tokenMatch[1];
  const res = await fetch('https://api.github.com/user', {
    headers: {
      'Authorization': `Bearer ${token}`,
      'Accept': 'application/vnd.github+json'
    }
  });

  const body = await res.text();
  const headers = Object.fromEntries(res.headers.entries());
  const scopes = headers['x-oauth-scopes'] || 'unknown';

  return new Response(JSON.stringify({
    authed: res.ok,
    status: res.status,
    scopes: scopes,
    user: res.ok ? JSON.parse(body) : null,
    error: res.ok ? null : body
  }, null, 2), { headers: { 'Content-Type': 'application/json' } });
}

