export async function onRequestGet(context) {
  const { request, env } = context;
  const url = new URL(request.url);
  const code = url.searchParams.get('code');
  const state = url.searchParams.get('state');
  const debug = url.searchParams.get('debug') === '1';

  const cookieHeader = request.headers.get('Cookie') || '';
  const stateMatch = cookieHeader.match(/gh_state=([^;]+)/);
  const savedState = stateMatch ? stateMatch[1] : '';
  const redirectMatch = cookieHeader.match(/gh_redirect=([^;]+)/);
  const redirect = redirectMatch ? decodeURIComponent(redirectMatch[1]) : '/blogs/';

  const errorInfo = {
    code_present: !!code,
    state_present: !!state,
    state_matches: state === savedState,
    cookie_header: cookieHeader,
    redirect: redirect
  };

  if (!code || !state || state !== savedState) {
    if (debug) {
      return new Response(JSON.stringify({ error: 'Invalid or missing OAuth state', info: errorInfo }, null, 2), { status: 400, headers: { 'Content-Type': 'application/json' } });
    }
    return new Response('Invalid or missing OAuth state', { status: 400 });
  }

  const tokenRes = await fetch('https://github.com/login/oauth/access_token', {
    method: 'POST',
    headers: {
      'Accept': 'application/json',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      client_id: env.GITHUB_CLIENT_ID,
      client_secret: env.GITHUB_CLIENT_SECRET,
      code
    })
  });

  const tokenData = await tokenRes.json();
  if (!tokenData.access_token) {
    if (debug) {
      return new Response(JSON.stringify({ error: 'GitHub authentication failed', token_response: tokenData }, null, 2), { status: 400, headers: { 'Content-Type': 'application/json' } });
    }
    return new Response('GitHub authentication failed', { status: 400 });
  }

  if (debug) {
    return new Response(JSON.stringify({
      success: true,
      token_prefix: tokenData.access_token.slice(0, 8) + '...',
      redirect: redirect,
      set_cookie: `gh_token=...; HttpOnly; Secure; SameSite=None; Path=/; Max-Age=604800`
    }, null, 2), { status: 200, headers: { 'Content-Type': 'application/json' } });
  }

  const headers = new Headers();
  headers.append('Location', redirect);
  headers.append('Set-Cookie', `gh_token=${tokenData.access_token}; HttpOnly; Secure; SameSite=None; Path=/; Max-Age=604800`);
  headers.append('Set-Cookie', 'gh_state=; HttpOnly; Secure; SameSite=None; Path=/; Max-Age=0');
  headers.append('Set-Cookie', 'gh_redirect=; HttpOnly; Secure; SameSite=None; Path=/; Max-Age=0');

  return new Response(null, { status: 302, headers });
}

