// Security utilities for API functions

const SITE_HOST = 'singhamarbir.com';

export function getOrigin(request) {
  const origin = request.headers.get('Origin');
  if (origin) return origin;
  const referer = request.headers.get('Referer');
  if (referer) {
    try {
      return new URL(referer).origin;
    } catch (e) {
      return null;
    }
  }
  return null;
}

export function isSameOrigin(request) {
  const url = new URL(request.url);
  const origin = getOrigin(request);
  if (!origin) return false;
  return origin === url.origin;
}

export function requireSameOrigin(request) {
  if (!isSameOrigin(request)) {
    return new Response(JSON.stringify({ error: 'Cross-origin request rejected' }), {
      status: 403,
      headers: { 'Content-Type': 'application/json' }
    });
  }
  return null;
}

export function validateRedirect(request, redirect) {
  if (!redirect) return '/blogs/';
  // Only allow relative paths starting with /
  if (/^\//.test(redirect) && !/\/\//.test(redirect)) {
    return redirect;
  }
  // Or same-origin absolute URLs
  try {
    const url = new URL(request.url);
    const redirectUrl = new URL(redirect, url.origin);
    if (redirectUrl.origin === url.origin) {
      return redirectUrl.pathname + redirectUrl.search;
    }
  } catch (e) {}
  return '/blogs/';
}

export function sanitizeIssue(issue) {
  if (!issue) return null;
  const str = String(issue).trim();
  if (!/^\d+$/.test(str)) return null;
  const num = parseInt(str, 10);
  if (num <= 0 || num > 999999999) return null;
  return num;
}

export function jsonError(message, status) {
  return new Response(JSON.stringify({ error: message }), {
    status,
    headers: { 'Content-Type': 'application/json' }
  });
}

export function jsonResponse(data) {
  return new Response(JSON.stringify(data), {
    headers: { 'Content-Type': 'application/json' }
  });
}

// Simple in-memory rate limiter per IP and action
const rateLimits = new Map();
const WINDOW_MS = 60 * 1000; // 1 minute
const MAX_REQUESTS = 10; // 10 likes/comments per minute per IP

export function checkRateLimit(request, action) {
  const clientIP = request.headers.get('CF-Connecting-IP') || 'unknown';
  const key = `${clientIP}:${action}`;
  const now = Date.now();
  const entry = rateLimits.get(key);

  if (!entry || now - entry.windowStart > WINDOW_MS) {
    rateLimits.set(key, { windowStart: now, count: 1 });
    return null;
  }

  entry.count++;
  if (entry.count > MAX_REQUESTS) {
    return jsonError('Rate limit exceeded. Please try again later.', 429);
  }
  return null;
}

export function sanitizeComment(text) {
  if (!text || typeof text !== 'string') return null;
  const trimmed = text.trim();
  if (!trimmed) return null;
  if (trimmed.length > 2000) return null;
  return trimmed;
}

export function getToken(request) {
  const cookieHeader = request.headers.get('Cookie') || '';
  const tokenMatch = cookieHeader.match(/gh_token=([^;]+)/);
  return tokenMatch ? tokenMatch[1] : null;
}

// Security headers middleware for all /api/* functions
import { requireSameOrigin } from './utils.js';

export async function onRequest(context) {
  const { request, next } = context;

  // Block cross-origin requests for state-changing methods
  if (request.method === 'POST' || request.method === 'DELETE' || request.method === 'PUT') {
    const blocked = requireSameOrigin(request);
    if (blocked) return blocked;
  }

  if (request.method === 'OPTIONS') {
    return new Response(null, {
      status: 204,
      headers: {
        'X-Content-Type-Options': 'nosniff',
        'X-Frame-Options': 'DENY',
        'Referrer-Policy': 'strict-origin-when-cross-origin'
      }
    });
  }

  const response = await next();
  const newResponse = new Response(response.body, response);
  newResponse.headers.set('X-Content-Type-Options', 'nosniff');
  newResponse.headers.set('X-Frame-Options', 'DENY');
  newResponse.headers.set('Referrer-Policy', 'strict-origin-when-cross-origin');
  return newResponse;
}

// Redirect to GitHub OAuth authorization
import { validateRedirect } from './utils.js';

export async function onRequestGet(context) {
  const { request, env } = context;
  const url = new URL(request.url);
  const redirect = validateRedirect(request, url.searchParams.get('redirect'));
  const state = crypto.randomUUID();

  const githubUrl = new URL('https://github.com/login/oauth/authorize');
  githubUrl.searchParams.set('client_id', env.GITHUB_CLIENT_ID);
  githubUrl.searchParams.set('redirect_uri', `${url.origin}/api/auth`);
  githubUrl.searchParams.set('scope', 'repo');
  githubUrl.searchParams.set('state', state);
  githubUrl.searchParams.set('allow_signup', 'true');

  const headers = new Headers();
  headers.append('Location', githubUrl.toString());
  headers.append('Set-Cookie', `gh_state=${state}; HttpOnly; Secure; SameSite=None; Path=/; Max-Age=600`);
  headers.append('Set-Cookie', `gh_redirect=${encodeURIComponent(redirect)}; HttpOnly; Secure; SameSite=None; Path=/; Max-Age=600`);

  return new Response(null, { status: 302, headers });
}

// Handle GitHub OAuth callback
import { validateRedirect, jsonResponse, jsonError } from './utils.js';

export async function onRequestGet(context) {
  const { request, env } = context;
  const url = new URL(request.url);
  const code = url.searchParams.get('code');
  const state = url.searchParams.get('state');

  const cookieHeader = request.headers.get('Cookie') || '';
  const stateMatch = cookieHeader.match(/gh_state=([^;]+)/);
  const savedState = stateMatch ? stateMatch[1] : '';
  const redirectMatch = cookieHeader.match(/gh_redirect=([^;]+)/);
  const redirect = redirectMatch ? validateRedirect(request, decodeURIComponent(redirectMatch[1])) : '/blogs/';

  if (!code || !state || state !== savedState) {
    return jsonError('Invalid or missing OAuth state', 400);
  }

  const tokenRes = await fetch('https://github.com/login/oauth/access_token', {
    method: 'POST',
    headers: {
      'Accept': 'application/json',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      client_id: env.GITHUB_CLIENT_ID,
      client_secret: env.GITHUB_CLIENT_SECRET,
      code
    })
  });

  const tokenData = await tokenRes.json();
  if (!tokenData.access_token) {
    return jsonError('GitHub authentication failed', 400);
  }

  const headers = new Headers();
  headers.append('Location', redirect);
  headers.append('Set-Cookie', `gh_token=${tokenData.access_token}; HttpOnly; Secure; SameSite=None; Path=/; Max-Age=604800`);
  headers.append('Set-Cookie', 'gh_state=; HttpOnly; Secure; SameSite=None; Path=/; Max-Age=0');
  headers.append('Set-Cookie', 'gh_redirect=; HttpOnly; Secure; SameSite=None; Path=/; Max-Age=0');

  return new Response(null, { status: 302, headers });
}

// Check current GitHub auth status
import { getToken, jsonResponse, jsonError } from './utils.js';

export async function onRequestGet(context) {
  const { request } = context;
  const token = getToken(request);

  if (!token) {
    return jsonResponse({ authed: false });
  }

  const res = await fetch('https://api.github.com/user', {
    headers: {
      'Authorization': `Bearer ${token}`,
      'Accept': 'application/vnd.github+json'
    }
  });

  if (!res.ok) {
    return jsonResponse({ authed: false });
  }

  const user = await res.json();
  return jsonResponse({ authed: true, user: user.login });
}

// Post a heart reaction to a GitHub issue
import { getToken, sanitizeIssue, jsonError, checkRateLimit } from './utils.js';

export async function onRequestPost(context) {
  const { request, env } = context;
  const token = getToken(request);

  if (!token) {
    return jsonError('Unauthorized', 401);
  }

  let body;
  try {
    body = await request.json();
  } catch (e) {
    return jsonError('Invalid JSON body', 400);
  }

  const issue = sanitizeIssue(body.issue);
  if (!issue) {
    return jsonError('Invalid issue number', 400);
  }

  const rateLimited = checkRateLimit(request, 'like');
  if (rateLimited) return rateLimited;

  const res = await fetch(`https://api.github.com/repos/a-5ingh/personal/issues/${issue}/reactions`, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${token}`,
      'Accept': 'application/vnd.github+json',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ content: 'heart' })
  });

  if (!res.ok) {
    const errText = await res.text();
    console.error('GitHub like API error:', res.status, errText);
    return jsonError('Unable to save like', res.status);
  }

  const data = await res.json();
  return jsonResponse(data);
}

// Post a comment to a GitHub issue
import { getToken, sanitizeIssue, sanitizeComment, jsonError, checkRateLimit, jsonResponse } from './utils.js';

